import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:intl/intl.dart';import '../../../core/providers/app_providers.dart';import '../../../core/domain/care_entities.dart';
class CalendarScreen extends ConsumerStatefulWidget{const CalendarScreen({super.key});@override ConsumerState<CalendarScreen> createState()=>_CalendarScreenState();}
class _CalendarScreenState extends ConsumerState<CalendarScreen>{DateTime selected=DateTime.now();@override Widget build(BuildContext context){final c=ref.watch(appControllerProvider);final all=c.items('reminders').map(Reminder.fromMap).toList();final events=all.where((e)=>e.dueAt.year==selected.year&&e.dueAt.month==selected.month&&e.dueAt.day==selected.day).toList()..sort((a,b)=>a.dueAt.compareTo(b.dueAt));return Scaffold(appBar:AppBar(title:const Text('Calendar agenda')),body:ListView(padding:const EdgeInsets.all(16),children:[CalendarDatePicker(initialDate:selected,firstDate:DateTime(2020),lastDate:DateTime(2100),onDateChanged:(d)=>setState(()=>selected=d)),Text(DateFormat.yMMMMd().format(selected),style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:10),if(events.isEmpty)const Text('No reminders on this day.') else ...events.map((e)=>Card(child:ListTile(leading:const Icon(Icons.event,color:Color(0xFF39845A)),title:Text(e.title),subtitle:Text('${e.category} · ${DateFormat.jm().format(e.dueAt)} · ${e.completed?'Completed':'Reminder'}'))))]));}}
